#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;
    while (n % 2 == 0) n /= 2;  // even divisors never give a run of consecutive integers
    long long divisors = 1;
    for (long long p = 3; p * p <= n; p += 2) {
        int exponent = 0;
        while (n % p == 0) {
            n /= p;
            exponent++;
        }
        divisors *= exponent + 1;
    }
    if (n > 1) divisors *= 2;
    cout << divisors - 1 << "\n";  // the odd divisor 1 is num on its own
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        long n = new Scanner(System.in).nextLong();
        while (n % 2 == 0) n /= 2; // even divisors never give a run of consecutive integers
        long divisors = 1;
        for (long p = 3; p * p <= n; p += 2) {
            int exponent = 0;
            while (n % p == 0) {
                n /= p;
                exponent++;
            }
            divisors *= exponent + 1;
        }
        if (n > 1) divisors *= 2;
        System.out.println(divisors - 1); // the odd divisor 1 is num on its own
    }
}

